import{G as e,W as t,n,rt as r}from"./chunks/framework.CNOAvfXG.js";var i=JSON.parse(`{"title":"并发模式（Concurrent Patterns）","description":"","frontmatter":{},"headers":[],"relativePath":"concurrency/overview.md","filePath":"concurrency/overview.md","lastUpdated":0}`),a={name:`concurrency/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="并发模式-concurrent-patterns" tabindex="-1">并发模式（Concurrent Patterns） <a class="header-anchor" href="#并发模式-concurrent-patterns" aria-label="Permalink to “并发模式（Concurrent Patterns）”">​</a></h1><p>并发模式（Concurrent Patterns）主要解决在多线程或多进程环境中如何有效、安全地协调和管理并发任务的问题。它们帮助开发者编写在并发情况下能够正确运行、性能高效且易于维护的程序。具体来说，并发模式解决以下几个核心问题：</p><ol><li><strong>线程安全</strong>：确保在多线程环境中共享资源的安全访问，避免竞态条件（Race Conditions）、死锁（Deadlocks）等问题。</li><li><strong>任务分配与协调</strong>：有效分配和调度并发任务，确保系统资源的最佳利用，同时保证任务的正确执行顺序。</li><li><strong>性能优化</strong>：通过并发执行提高系统的吞吐量和响应速度，尽量减少锁争用和上下文切换开销。</li><li><strong>可维护性与可扩展性</strong>：通过抽象和封装并发处理逻辑，提高代码的可维护性和可扩展性，减少错误。</li></ol>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};